package glitch

import data.glitch_lib

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    node.type == "iam_policy"

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    attr.name in {"action", "actions", "resource", "resources"}
    attr.value.ir_type == "String"
    (attr.value.value == "*" or regex.match(".*:\*", attr.value.value) or regex.match("(?i)AdministratorAccess", attr.value.value))

    result := {
        "type": "sec_def_admin",
        "element": attr,
        "path": parent.path,
        "description": "Overly permissive IAM policy - Avoid wildcard actions/resources or admin privileges. (CWE-250)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    node.type in {"container", "pod", "security_context"}

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    (attr.name == "privileged" and attr.value.ir_type == "Boolean" and attr.value.value == true) or
    (attr.name == "runAsUser" and (attr.value.ir_type == "Integer" and attr.value.value == 0)) or
    (attr.name == "runAsUser" and (attr.value.ir_type == "String" and attr.value.value == "0")) or
    (attr.name == "runAsGroup" and (attr.value.ir_type == "Integer" and attr.value.value == 0)) or
    (attr.name == "allowPrivilegeEscalation" and attr.value.ir_type == "Boolean" and attr.value.value == true)

    result := {
        "type": "sec_def_admin",
        "element": attr,
        "path": parent.path,
        "description": "Container with excessive privileges - Avoid privileged mode or root execution. (CWE-250)"
    }
}

check_permission(value) {
    value.ir_type == "String"
    regex.match("(?:^0?777$)|(?:(?:^|(?:ugo)|o|a)\\+[rwx]{3})", value.value)
} else {
    value.ir_type == "Integer"
    value.value == 777
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    node.type in {"file", "file_resource"}

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    attr.name in {"mode", "m"}
    check_permission(attr.value)

    result := {
        "type": "sec_def_admin",
        "element": attr,
        "path": parent.path,
        "description": "Full permission to the filesystem - Files should not have full permissions. (CWE-250)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    node.type in {"file", "file_resource"}

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    attr.name in {"owner", "user", "group"}
    attr.value.ir_type == "String"
    attr.value.value == "root"

    result := {
        "type": "sec_def_admin",
        "element": attr,
        "path": parent.path,
        "description": "Root ownership of files - Avoid root ownership for non-system files. (CWE-250)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    node.type in {"instance", "vm", "compute"}

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    attr.name in {"user", "username", "default_user"}
    attr.value.ir_type == "String"
    attr.value.value in {"root", "administrator"}

    result := {
        "type": "sec_def_admin",
        "element": attr,
        "path": parent.path,
        "description": "Compute instance running as root - Avoid root privileges. (CWE-250)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    node.type in {"network", "security_group", "firewall"}

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    (attr.name in {"source", "cidr", "source_cidr"} and attr.value.ir_type == "String" and attr.value.value == "0.0.0.0/0") or
    (attr.name in {"port", "ports", "port_range"} and attr.value.ir_type == "String" and attr.value.value == "*")

    result := {
        "type": "sec_def_admin",
        "element": attr,
        "path": parent.path,
        "description": "Overly permissive network policy - Avoid open access to services. (CWE-250)"
    }
}

